function escapeForXmlFilter(value) {
  return String(value).replace(/"/g, '\\"');
}

const input = $json;

// 🔤 LANGUAGE MAP
const languageMap = {
  czech: 'cs_CZ',
  english: 'en_US',
  german: 'de_DE',
  polish: 'pl_PL'
};

// 👥 TARGET GROUP MAP
const targetGroupMap = {
  developers: 'developer',
  architects: 'architect',
  designers: 'designer',
  general: null
};

// 👉 resolve values
const languageKey = input.language || 'czech';
const targetGroupKey = input.target_group || 'general';

if (!(languageKey in languageMap)) {
  throw new Error(`Unsupported language: ${languageKey}`);
}

if (!(targetGroupKey in targetGroupMap)) {
  throw new Error(`Unsupported target_group: ${targetGroupKey}`);
}

const language = languageMap[languageKey];
const industryValue = targetGroupMap[targetGroupKey];

// 🧱 BUILD CONDITIONS
const conditions = [
  '("is_blacklisted", "=", False)',
  `("lang", "=", "${escapeForXmlFilter(language)}")`
];

if (industryValue !== null) {
  conditions.push(`("industry_id", "ilike", "${escapeForXmlFilter(industryValue)}")`);
}

conditions.push('("category_id", "in", [30])');

// 🔗 ADD OPERATORS
const operators = Array(Math.max(conditions.length - 1, 0)).fill('"&"');

// 🧾 FINAL FILTER
const filterBody = `[${[...operators, ...conditions].join(', ')}]`;
const xmlFilter = `<![CDATA[\n${filterBody}\n]]>`;

return [
  {
    json: {
      ...input,
      resolved_language: language,
      resolved_target_group: industryValue,
      xml_filter: xmlFilter
    }
  }
];
